    end
    AddValue(BaseEndurance, 2)
    evt.StatusText("Clear water from deep under the sand. You feel it in your bones. (+2 Endurance, permanent)", 6)
    SetPlayerBit(PlayerBit(11330))
end, "The oasis fountain")

